(6557,	15,	'2018-04-03 19:46:33',	'2018-04-04 01:46:33',	'<iframe width=\"500\" height=\"281\" src=\"https://www.youtube.com/embed/kPgeSV32uZg?feature=oembed\" frameborder=\"0\" allow=\"autoplay; encrypted-media\" allowfullscreen></iframe>',	'',	'',	'publish',	'closed',	'closed',	'',	'1ece4d3f0dde82f508519d54634fa429',	'',	'',	'2018-04-03 19:46:33',	'2018-04-04 01:46:33',	'',	0,	'https://bestsaxophonewebsiteevercom.local/1ece4d3f0dde82f508519d54634fa429/',	0,	'oembed_cache',	'',	0,	0),
