(6751,	0,	'2018-07-13 11:25:16',	'2018-07-13 17:25:16',	'<iframe width=\"500\" height=\"375\" src=\"https://www.youtube.com/embed/BlwGWz48FVc?feature=oembed\" frameborder=\"0\" allow=\"autoplay; encrypted-media\" allowfullscreen></iframe>',	'',	'',	'publish',	'closed',	'closed',	'',	'c6bfd19f720a6be117670333e4f7e5e3',	'',	'',	'2018-07-13 11:25:16',	'2018-07-13 17:25:16',	'',	0,	'https://bestsaxophonewebsiteevercom.local/c6bfd19f720a6be117670333e4f7e5e3/',	0,	'oembed_cache',	'',	0,	0),
