(6830,	0,	'2018-07-24 11:00:38',	'2018-07-24 17:00:38',	'<iframe width=\"500\" height=\"375\" src=\"https://www.youtube.com/embed/bh8qzHth8xA?feature=oembed\" frameborder=\"0\" allow=\"autoplay; encrypted-media\" allowfullscreen></iframe>',	'',	'',	'publish',	'closed',	'closed',	'',	'f3a368a226496f916961c3dd9faccb98',	'',	'',	'2018-07-24 11:00:38',	'2018-07-24 17:00:38',	'',	0,	'https://bestsaxophonewebsiteevercom.local/f3a368a226496f916961c3dd9faccb98/',	0,	'oembed_cache',	'',	0,	0),
