(6927,	0,	'2018-10-04 11:21:27',	'2018-10-04 17:21:27',	'<iframe width=\"500\" height=\"281\" src=\"https://www.youtube.com/embed/vLGEX0ijsn8?feature=oembed\" frameborder=\"0\" allow=\"autoplay; encrypted-media\" allowfullscreen></iframe>',	'',	'',	'publish',	'closed',	'closed',	'',	'c5b71285c45b301f82214f35f6c9e324',	'',	'',	'2018-10-04 11:21:27',	'2018-10-04 17:21:27',	'',	0,	'https://bestsaxophonewebsiteevercom.local/c5b71285c45b301f82214f35f6c9e324/',	0,	'oembed_cache',	'',	0,	0),
